import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";

const rounds = JSON.parse(readFileSync("rounds.json", "utf8")); // what the reviewer said in each round
const normalise = (body) => body.toLowerCase().replace(/\d+/g, "#").replace(/\s+/g, " ").trim();
const fingerprint = (f) => createHash("sha1").update(`${f.path}|${f.rule}|${normalise(f.body)}`).digest("hex").slice(0, 8);

let found = 0;
const fixed = new Set();
const left = new Map(); // fingerprint -> reason

for (let round = 1; ; round++) {
  const findings = rounds[round - 1] ?? []; // stands in for a fresh reviewer session
  const important = findings.filter((f) => f.severity === "important" && !left.has(fingerprint(f)));
  if (important.length === 0) break;
  found += important.length;
  for (const f of important) {
    const fp = fingerprint(f);
    if (fixed.has(fp)) {
      left.set(fp, "it came back after a fix; asked the requester");
      console.log(`round ${round}  ${fp}  ${f.path}:${f.line}  came back after a fix → ask the requester`);
    } else {
      fixed.add(fp); // stands in for Nova fixing it
      console.log(`round ${round}  ${fp}  ${f.path}:${f.line}  fixed`);
    }
  }
  console.log(`round ${round}  rerun the QA checks`);
}

const reasons = [...left.values()].map((r) => `, because ${r}`).join("");
console.log(`\nFound ${found} · fixed ${fixed.size} · left ${left.size}${reasons}`);

